27dc05196 SecureChannel: Split UA_SecureChannel_close and UA_SecureChannel_deleteMembers
 src/client/ua_client_connect.c              |  3 ++-
 src/client/ua_client_connect_async.c        |  3 ++-
 src/server/ua_securechannel_manager.c       |  8 ++++++--
 src/server/ua_server_binary.c               | 12 ++++++++----
 src/ua_securechannel.c                      | 26 +++++++++++++++++++-------
 src/ua_securechannel.h                      |  4 +++-
 tests/check_securechannel.c                 |  6 ++++--
 tests/server/check_server_monitoringspeed.c |  3 ++-
 tests/server/check_server_readspeed.c       |  3 ++-
 9 files changed, 48 insertions(+), 20 deletions(-)
commit 27dc05196fc43036a2efcea060ae3711b3209cf2
Author: Julius Pfrommer <julius.pfrommer@web.de>
Date:   Sun Sep 23 14:04:35 2018 +0200

    SecureChannel: Split UA_SecureChannel_close and UA_SecureChannel_deleteMembers

    OSS-Fuzz uncovered an issue where we "unlinking" of the Session and
    Connection was done in a delayed callback. But the "unlinking" needs to
    be done right away.

diff --git a/src/client/ua_client_connect.c b/src/client/ua_client_connect.c
index 6320f2080..a1ba687d3 100644
--- a/src/client/ua_client_connect.c
+++ b/src/client/ua_client_connect.c
@@ -697,61 +697,62 @@ UA_Client_connect_username(UA_Client *client, const char *endpointUrl,
 /************************/

 static void
 sendCloseSession(UA_Client *client) {
     UA_CloseSessionRequest request;
     UA_CloseSessionRequest_init(&request);

     request.requestHeader.timestamp = UA_DateTime_now();
     request.requestHeader.timeoutHint = 10000;
     request.deleteSubscriptions = true;
     UA_CloseSessionResponse response;
     __UA_Client_Service(client, &request, &UA_TYPES[UA_TYPES_CLOSESESSIONREQUEST],
                         &response, &UA_TYPES[UA_TYPES_CLOSESESSIONRESPONSE]);
     UA_CloseSessionRequest_deleteMembers(&request);
     UA_CloseSessionResponse_deleteMembers(&response);
 }

 static void
 sendCloseSecureChannel(UA_Client *client) {
     UA_SecureChannel *channel = &client->channel;
     UA_CloseSecureChannelRequest request;
     UA_CloseSecureChannelRequest_init(&request);
     request.requestHeader.requestHandle = ++client->requestHandle;
     request.requestHeader.timestamp = UA_DateTime_now();
     request.requestHeader.timeoutHint = 10000;
     request.requestHeader.authenticationToken = client->authenticationToken;
     UA_SecureChannel_sendSymmetricMessage(channel, ++client->requestId,
                                           UA_MESSAGETYPE_CLO, &request,
                                           &UA_TYPES[UA_TYPES_CLOSESECURECHANNELREQUEST]);
     UA_CloseSecureChannelRequest_deleteMembers(&request);
-    UA_SecureChannel_deleteMembersCleanup(&client->channel);
+    UA_SecureChannel_close(&client->channel);
+    UA_SecureChannel_deleteMembers(&client->channel);
 }

 UA_StatusCode
 UA_Client_disconnect(UA_Client *client) {
     /* Is a session established? */
     if(client->state >= UA_CLIENTSTATE_SESSION) {
         client->state = UA_CLIENTSTATE_SECURECHANNEL;
         sendCloseSession(client);
     }
     UA_NodeId_deleteMembers(&client->authenticationToken);
     client->requestHandle = 0;

     /* Is a secure channel established? */
     if(client->state >= UA_CLIENTSTATE_SECURECHANNEL) {
         client->state = UA_CLIENTSTATE_CONNECTED;
         sendCloseSecureChannel(client);
     }

     /* Close the TCP connection */
     if(client->connection.state != UA_CONNECTION_CLOSED
             && client->connection.state != UA_CONNECTION_OPENING)
         /*UA_ClientConnectionTCP_init sets initial state to opening */
         if(client->connection.close != NULL)
             client->connection.close(&client->connection);


 #ifdef UA_ENABLE_SUBSCRIPTIONS
 // TODO REMOVE WHEN UA_SESSION_RECOVERY IS READY
     /* We need to clean up the subscriptions */
     UA_Client_Subscriptions_clean(client);
diff --git a/src/client/ua_client_connect_async.c b/src/client/ua_client_connect_async.c
index d97011227..3860d6d1d 100644
--- a/src/client/ua_client_connect_async.c
+++ b/src/client/ua_client_connect_async.c
@@ -630,61 +630,62 @@ UA_Client_connect_async(UA_Client *client, const char *endpointUrl,
     retval = UA_SecureChannel_generateNewKeys(&client->channel);
     if(retval != UA_STATUSCODE_GOOD)
         goto cleanup;

     return retval;

  cleanup:
     UA_LOG_TRACE(client->config.logger, UA_LOGCATEGORY_CLIENT,
                  "Failure during async connect");
     UA_Client_disconnect(client);
     return retval;
 }

 /* Async disconnection */
 static void
 sendCloseSecureChannelAsync(UA_Client *client, void *userdata,
                              UA_UInt32 requestId, void *response) {
     UA_NodeId_deleteMembers (&client->authenticationToken);
     client->requestHandle = 0;

     UA_SecureChannel *channel = &client->channel;
     UA_CloseSecureChannelRequest request;
     UA_CloseSecureChannelRequest_init(&request);
     request.requestHeader.requestHandle = ++client->requestHandle;
     request.requestHeader.timestamp = UA_DateTime_now();
     request.requestHeader.timeoutHint = 10000;
     request.requestHeader.authenticationToken = client->authenticationToken;
     UA_SecureChannel_sendSymmetricMessage(
             channel, ++client->requestId, UA_MESSAGETYPE_CLO, &request,
             &UA_TYPES[UA_TYPES_CLOSESECURECHANNELREQUEST]);
-    UA_SecureChannel_deleteMembersCleanup(&client->channel);
+    UA_SecureChannel_close(&client->channel);
+    UA_SecureChannel_deleteMembers(&client->channel);
 }

 static void
 sendCloseSessionAsync(UA_Client *client, UA_UInt32 *requestId) {
     UA_CloseSessionRequest request;
     UA_CloseSessionRequest_init(&request);

     request.requestHeader.timestamp = UA_DateTime_now();
     request.requestHeader.timeoutHint = 10000;
     request.deleteSubscriptions = true;

     UA_Client_sendAsyncRequest(
             client, &request, &UA_TYPES[UA_TYPES_CLOSESESSIONREQUEST],
             (UA_ClientAsyncServiceCallback) sendCloseSecureChannelAsync,
             &UA_TYPES[UA_TYPES_CLOSESESSIONRESPONSE], NULL, requestId);

 }

 UA_StatusCode
 UA_Client_disconnect_async(UA_Client *client, UA_UInt32 *requestId) {
     /* Is a session established? */
     if (client->state == UA_CLIENTSTATE_SESSION) {
         client->state = UA_CLIENTSTATE_SESSION_DISCONNECTED;
         sendCloseSessionAsync(client, requestId);
     }

     /* Close the TCP connection
      * shutdown and close (in tcp.c) are already async*/
     if (client->state >= UA_CLIENTSTATE_CONNECTED)
         client->connection.close(&client->connection);
diff --git a/src/server/ua_securechannel_manager.c b/src/server/ua_securechannel_manager.c
